// Tests of the local i18n.ts (generated by tools/rinomina.mjs): Italian is built in, English is a file fetched on demand.
// Each case loads a fresh copy of the module (the query string makes the module URL unique), because the fetched
// tables are kept in module state.

import assert from "node:assert/strict";
import { afterEach, describe, it } from "node:test";

import type { HomeAssistant } from "./types.ts";

type I18n = typeof import("./i18n.ts");
let counter = 0;
const fresh = (): Promise<I18n> => import(`./i18n.ts?case=${++counter}`) as Promise<I18n>;

const host = (language: string): HomeAssistant => ({ language }) as unknown as HomeAssistant;
const realFetch = globalThis.fetch;
const urls: string[] = [];

/** Replaces fetch with a fake that records the address and answers with `answer`. */
function fakeFetch(answer: () => Promise<Response>): void {
  globalThis.fetch = ((input: RequestInfo | URL) => {
    urls.push(String(input));
    return answer();
  }) as typeof fetch;
}
const json = (body: unknown, ok = true): Promise<Response> => Promise.resolve({ ok, json: () => Promise.resolve(body) } as Response);

afterEach(() => {
  globalThis.fetch = realFetch;
  urls.length = 0;
});

describe("i18n: Italian is built in", () => {
  it("the default table is Italian, with no network request", async () => {
    fakeFetch(() => json({}));
    const { translate, languageReady, languageCode } = await fresh();
    assert.equal(translate(host("it"), "all_floors"), "Tutti i piani");
    assert.equal(languageCode("it"), null);
    assert.equal(languageReady("it"), true);
    assert.equal(urls.length, 0);
  });

  it("a language that is not shipped (German) stays on Italian", async () => {
    const { translate, languageCode, loadLanguage } = await fresh();
    assert.equal(languageCode("de"), null);
    await loadLanguage("de");
    assert.equal(translate(host("de"), "all_floors"), "Tutti i piani");
  });

  it("replaces the {name} placeholders", async () => {
    const { translate } = await fresh();
    assert.equal(translate(host("it"), "save_failed_detail", { error: "rete" }), "Salvataggio non riuscito: rete. Le tue modifiche restano in questo browser.");
  });
});

describe("i18n: English only after loadLanguage", () => {
  it("is Italian before the file is fetched, English after, and a missing key falls back to Italian", async () => {
    fakeFetch(() => json({ all_floors: "All floors" }));
    const { translate, languageReady, loadLanguage } = await fresh();
    assert.equal(languageReady("en-GB"), false);
    assert.equal(translate(host("en"), "all_floors"), "Tutti i piani");
    await loadLanguage("en-GB");
    assert.equal(languageReady("en"), true);
    assert.equal(translate(host("en"), "all_floors"), "All floors");
    assert.equal(translate(host("en"), "no_building"), "Nessuna planimetria ancora.");
    assert.equal(translate(host("it"), "all_floors"), "Tutti i piani");
  });

  it("fetches the file once, from an address relative to the module", async () => {
    fakeFetch(() => json({ all_floors: "All floors" }));
    const { loadLanguage } = await fresh();
    await Promise.all([loadLanguage("en"), loadLanguage("en")]);
    await loadLanguage("en");
    assert.equal(urls.length, 1);
    assert.equal(urls[0], new URL("./lang/en.json?v=0", import.meta.url).href);
  });
});

describe("i18n: a missing or broken file leaves Italian", () => {
  const cases: Array<[string, () => Promise<Response>]> = [
    ["the request fails", () => Promise.reject(new Error("offline"))],
    ["the answer is not ok", () => json({ all_floors: "All floors" }, false)],
    ["the body is not JSON", () => Promise.resolve({ ok: true, json: () => Promise.reject(new SyntaxError("bad")) } as Response)],
    ["the body is not an object", () => json(null)],
  ];
  for (const [name, answer] of cases) {
    it(name, async () => {
      fakeFetch(answer);
      const { translate, languageReady, loadLanguage } = await fresh();
      await loadLanguage("en");
      assert.equal(languageReady("en"), true);
      assert.equal(translate(host("en"), "all_floors"), "Tutti i piani");
      assert.equal(urls.length, 1);
    });
  }
});
